import pytest
from solution import detect_language

def test_detect_language_filipino():
    assert detect_language("Ano po, ano po.") == 'FILIPINO'

def test_detect_language_japanese():
    assert detect_language("Konnichiwa, desu ne.") == 'JAPANESE'
    assert detect_language("Konnichiwa, masu desu.") == 'JAPANESE'

def test_detect_language_korean():
    assert detect_language("Annyeonghaseyo, mnida.") == 'KOREAN'

def test_detect_language_english():
    with pytest.raises(ValueError, match="Sentence does not end with a recognized suffix."):
        detect_language("Hello, world!")

def test_detect_language_mixed_suffixes():
    with pytest.raises(ValueError, match="Sentence does not end with a recognized suffix."):
        detect_language("Ano desu, masu ne, mnida.")

def test_detect_language_no_suffix():
    with pytest.raises(ValueError, match="Sentence does not end with a recognized suffix."):
        detect_language("Hello, world!")
